from __future__ import absolute_import, division
import time
from builtins import range
from past.utils import old_div
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.parameters import Parameters
from taf.ul.trs_e2e_fw.lib.oam.exceptions import BtsOnAirException, BtsNotOnAirException
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class CellOperations(BaseClass):
    """Cell Operations"""
    def __init__(self):
        super(CellOperations, self).__init__()
        self.parameters = Parameters()

    @check_rat
    def verify_bts_status(self, **kwargs):
        """ This function verifies bts is on air or not, considering status of all available RAT
            cells
            :param should_be_onair: BTS should be on air or not
            :param wait_for: Time to wait(seconds) before checking for status
            :param alias: Name of execution context
        """
        should_be_onair = kwargs.pop('should_be_onair', True)
        wait_for = kwargs.pop('wait_for', 60)
        timeout = kwargs.pop('timeout', 60)
        alias = kwargs.pop('alias', 'default')
        bts_on_air = True
        if should_be_onair is True:
            for iter in range(old_div(int(wait_for), 10)):
                time.sleep(10)
                bts_on_air = self._verify_bts_status(alias)
                if bts_on_air:
                    logger.debug('bts_on_air:{}'.format(bts_on_air))
                    return bts_on_air
                else:
                    raise BtsNotOnAirException
        elif should_be_onair is False:
            bts_on_air = self._verify_bts_status(alias)
            if bts_on_air is not False:
                raise BtsOnAirException
        logger.debug('bts_on_air:{}'.format(bts_on_air))
        return bts_on_air

    def _verify_bts_status(self, alias):
        logger.info("Verifying BTS status ....")
#        param_path = 'LTEENB-0:x2LinkStatus'
        param_path = 'NRBTS-1:operationalState'
        try:
            status = self.parameters.get_parameter(param_path=param_path, alias=alias)
            logger.debug("status is :{}".format(status))
            if status.lower() == 'onair':
                return True
            else:
                return False
        except Exception as e:
            logger.error("NRBTS-1:operationalState is not available to check btsOnAir Status due to :{}".format(e))
